package com.ebanking.ekycservice.service;

import com.ebanking.ekycservice.constant.EkycStatus;
import com.ebanking.ekycservice.constant.EkycStep;
import com.ebanking.ekycservice.dto.request.LivenessRequest;
import com.ebanking.ekycservice.dto.request.OrcRequest;
import com.ebanking.ekycservice.dto.response.FaceMatchResponse;
import com.ebanking.ekycservice.dto.response.LivenessResponse;
import com.ebanking.ekycservice.dto.response.OrcResponse;
import com.ebanking.ekycservice.dto.response.SessionResponse;
import com.ebanking.ekycservice.entity.BiometricData;
import com.ebanking.ekycservice.entity.DocumentInfo;
import com.ebanking.ekycservice.entity.EkycSession;
import com.ebanking.ekycservice.exception.EkycException;
import com.ebanking.ekycservice.repository.BiometricDataRepository;
import com.ebanking.ekycservice.repository.DocumentInfoRepository;
import com.ebanking.ekycservice.repository.EkycSessionRepository;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Map;
import java.util.UUID;

@Slf4j
@Service
@RequiredArgsConstructor
public class EkycService {

    private final EkycSessionRepository sessionRepository;
    private final DocumentInfoRepository documentInfoRepository;
    private final BiometricDataRepository biometricDataRepository;
    private final FptAiService fptAiService;

    @Transactional
    public SessionResponse createSession(Long userId) {
        log.info("Creating session for user: {}", userId);

        EkycSession session = EkycSession.builder()
                .userId(userId)
                .status(EkycStatus.INITIATED)
                .currentStep(EkycStep.OCR)
                .expiredAt(LocalDateTime.now().plusMinutes(10))
                .build();

        session = sessionRepository.save(session);

        return SessionResponse.builder()
                .sessionId(session.getId().toString())
                .status(session.getStatus())
                .currentStep(session.getCurrentStep())
                .expiresAt(session.getExpiredAt())
                .build();
    }

    @Transactional
    @SuppressWarnings("unchecked")
    public OrcResponse processOcr(OrcRequest request) {
        log.info("Processing OCR for session: {}", request.getSessionId());

        // Validate session
        EkycSession session = sessionRepository.findById(UUID.fromString(request.getSessionId()))
                .orElseThrow(() -> new EkycException("Session not found"));

        if (session.getExpiredAt().isBefore(LocalDateTime.now())) {
            throw new EkycException("Session expired");
        }

        // Call FPT.AI OCR for front image
        Map<String, Object> frontResult = fptAiService.callOrcApi(request.getFrontImageBase64());
        Map<String, Object> frontData = (Map<String, Object>) frontResult.get("data");

        // Call FPT.AI OCR for back image
        Map<String, Object> backResult = fptAiService.callOrcApi(request.getBackImageBase64());
        Map<String, Object> backData = (Map<String, Object>) backResult.get("data");

        // Extract data
        String idNumber = (String) frontData.get("id");
        String fullName = (String) frontData.get("name");
        String dobStr = (String) frontData.get("dob");
        String gender = (String) frontData.get("sex");
        String address = backData != null ? (String) backData.get("address") : "";

        // Parse date
        LocalDate dateOfBirth = parseDateOfBirth(dobStr);

        // Save document info
        DocumentInfo documentInfo = DocumentInfo.builder()
                .session(session)
                .idNumber(idNumber)
                .fullName(fullName)
                .dateOfBirth(dateOfBirth)
                .gender(gender)
                .address(address)
                .frontImageUrl(request.getFrontImageBase64()) // Storing base64 directly (simplified)
                .backImageUrl(request.getBackImageBase64())
                .portraitImageUrl((String) frontData.get("avatar"))
                .build();

        documentInfoRepository.save(documentInfo);

        // Update session
        session.setStatus(EkycStatus.OCR_COMPLETED);
        session.setCurrentStep(EkycStep.VERIFICATION);
        sessionRepository.save(session);

        return OrcResponse.builder()
                .sessionId(session.getId().toString())
                .idNumber(idNumber)
                .fullName(fullName)
                .dateOfBirth(dateOfBirth)
                .gender(gender)
                .address(address)
                .portraitImageUrl((String) frontData.get("avatar"))
                .build();
    }

    @Transactional
    @SuppressWarnings("unchecked")
    public LivenessResponse processLiveness(LivenessRequest request) {
        log.info("Processing liveness for session: {}", request.getSessionId());

        // Validate session
        EkycSession session = sessionRepository.findById(UUID.fromString(request.getSessionId()))
                .orElseThrow(() -> new EkycException("Session not found"));

        // Call FPT.AI Liveness
        Map<String, Object> result = fptAiService.callLivenessApi(request.getVideoBase64());
        Map<String, Object> data = (Map<String, Object>) result.get("data");

        Boolean isLive = (Boolean) data.get("is_live");
        Double score = ((Number) data.get("score")).doubleValue();

        // Save biometric data
        BiometricData biometricData = BiometricData.builder()
                .session(session)
                .selfieVideoUrl(request.getVideoBase64()) // Storing base64 directly
                .livenessScore(score)
                .isLive(isLive)
                .build();

        biometricDataRepository.save(biometricData);

        // Update session
        session.setStatus(EkycStatus.LIVENESS_COMPLETED);
        session.setCurrentStep(EkycStep.FACE_MATCH);
        sessionRepository.save(session);

        return LivenessResponse.builder()
                .isLive(isLive)
                .confidence(score)
                .build();
    }

    @Transactional
    @SuppressWarnings("unchecked")
    public FaceMatchResponse processFaceMatch(String sessionId) {
        log.info("Processing face match for session: {}", sessionId);

        // Get session with relations
        EkycSession session = sessionRepository.findById(UUID.fromString(sessionId))
                .orElseThrow(() -> new EkycException("Session not found"));

        DocumentInfo docInfo = session.getDocumentInfo();
        BiometricData bioData = session.getBiometricData();

        if (docInfo == null || bioData == null) {
            throw new EkycException("Missing required data for face matching");
        }

        // Extract frame from video (simplified - using video base64 directly)
        String portraitImage = docInfo.getPortraitImageUrl();
        String selfieImage = bioData.getSelfieVideoUrl(); // In production, extract frame from video

        // Call FPT.AI Face Match
        Map<String, Object> result = fptAiService.callFaceMatchApi(portraitImage, selfieImage);
        Map<String, Object> data = (Map<String, Object>) result.get("data");

        Double similarity = ((Number) data.get("similarity")).doubleValue();
        Boolean isMatched = similarity >= 0.85;

        // Update biometric data
        bioData.setFaceMatchScore(similarity);
        bioData.setIsMatched(isMatched);
        biometricDataRepository.save(bioData);

        // Update session
        if (isMatched) {
            session.setStatus(EkycStatus.COMPLETED);
            session.setCurrentStep(EkycStep.COMPLETE);
        } else {
            session.setStatus(EkycStatus.FAILED);
        }
        sessionRepository.save(session);

        return FaceMatchResponse.builder()
                .isMatched(isMatched)
                .confidence(similarity)
                .build();
    }

    private LocalDate parseDateOfBirth(String dobStr) {
        try {
            DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
            return LocalDate.parse(dobStr, formatter);
        } catch (Exception e) {
            log.warn("Failed to parse date: {}", dobStr);
            return null;
        }
    }
}

package com.ebanking.ekycservice.service;

import com.ebanking.ekycservice.constant.EkycStatus;
import com.ebanking.ekycservice.constant.EkycStep;
import com.ebanking.ekycservice.dto.request.LivenessRequest;
import com.ebanking.ekycservice.dto.request.OrcRequest;
import com.ebanking.ekycservice.dto.response.FaceMatchResponse;
import com.ebanking.ekycservice.dto.response.LivenessResponse;
import com.ebanking.ekycservice.dto.response.OrcResponse;
import com.ebanking.ekycservice.dto.response.SessionResponse;
import com.ebanking.ekycservice.entity.BiometricData;
import com.ebanking.ekycservice.entity.DocumentInfo;
import com.ebanking.ekycservice.entity.EkycSession;
import com.ebanking.ekycservice.exception.EkycException;
import com.ebanking.ekycservice.repository.BiometricDataRepository;
import com.ebanking.ekycservice.repository.DocumentInfoRepository;
import com.ebanking.ekycservice.repository.EkycSessionRepository;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Map;
import java.util.UUID;

@Slf4j
@Service
@RequiredArgsConstructor
public class EkycService {

    private final EkycSessionRepository sessionRepository;
    private final DocumentInfoRepository documentInfoRepository;
    private final BiometricDataRepository biometricDataRepository;
    private final FptAiService fptAiService;

    @Transactional
    public SessionResponse createSession(Long userId) {
        log.info("Creating session for user: {}", userId);

        EkycSession session = EkycSession.builder()
                .userId(userId)
                .status(EkycStatus.INITIATED)
                .currentStep(EkycStep.OCR)
                .expiredAt(LocalDateTime.now().plusMinutes(10))
                .build();

        session = sessionRepository.save(session);

        return SessionResponse.builder()
                .sessionId(session.getId().toString())
                .status(session.getStatus())
                .currentStep(session.getCurrentStep())
                .expiresAt(session.getExpiredAt())
                .build();
    }

    @Transactional
    @SuppressWarnings("unchecked")
    public OrcResponse processOcr(OrcRequest request) {
        log.info("Processing OCR for session: {}", request.getSessionId());

        // Validate session
        EkycSession session = sessionRepository.findById(UUID.fromString(request.getSessionId()))
                .orElseThrow(() -> new EkycException("Session not found"));

        if (session.getExpiredAt().isBefore(LocalDateTime.now())) {
            throw new EkycException("Session expired");
        }

        try {
            // Call FPT.AI OCR for front image
            Map<String, Object> frontResult = fptAiService.callOrcApi(request.getFrontImageBase64());
            log.debug("Front OCR result: {}", frontResult);

            // FPT.AI OCR response structure: { "errorCode": 0, "errorMessage": "", "data": [...] }
            Object dataObj = frontResult.get("data");
            if (dataObj == null) {
                throw new EkycException("FPT.AI returned null data for front image");
            }

            // Data is an array, get the first element
            java.util.List<Map<String, Object>> frontDataList = (java.util.List<Map<String, Object>>) dataObj;
            if (frontDataList.isEmpty()) {
                throw new EkycException("FPT.AI returned empty data for front image");
            }
            Map<String, Object> frontData = frontDataList.get(0);

            // Call FPT.AI OCR for back image
            Map<String, Object> backResult = fptAiService.callOrcApi(request.getBackImageBase64());
            log.debug("Back OCR result: {}", backResult);

            Object backDataObj = backResult.get("data");
            Map<String, Object> backData = null;
            if (backDataObj != null) {
                java.util.List<Map<String, Object>> backDataList = (java.util.List<Map<String, Object>>) backDataObj;
                if (!backDataList.isEmpty()) {
                    backData = backDataList.get(0);
                }
            }

            // Extract data with safe casting
            String idNumber = getStringValue(frontData, "id");
            String fullName = getStringValue(frontData, "name");
            String dobStr = getStringValue(frontData, "dob");
            String gender = getStringValue(frontData, "sex");
            String address = backData != null ? getStringValue(backData, "address") : "";
            String portraitImage = getStringValue(frontData, "avatar");

            log.info("Extracted data: idNumber={}, fullName={}, dob={}, gender={}", 
                    idNumber, fullName, dobStr, gender);

            // Parse date
            LocalDate dateOfBirth = parseDateOfBirth(dobStr);

            // Save document info
            DocumentInfo documentInfo = DocumentInfo.builder()
                    .session(session)
                    .idNumber(idNumber)
                    .fullName(fullName)
                    .dateOfBirth(dateOfBirth)
                    .gender(gender)
                    .address(address)
                    .frontImageUrl(request.getFrontImageBase64()) // Storing base64 directly (simplified)
                    .backImageUrl(request.getBackImageBase64())
                    .portraitImageUrl(portraitImage)
                    .build();

            documentInfoRepository.save(documentInfo);

            // Update session
            session.setStatus(EkycStatus.OCR_COMPLETED);
            session.setCurrentStep(EkycStep.VERIFICATION);
            sessionRepository.save(session);

            return OrcResponse.builder()
                    .sessionId(session.getId().toString())
                    .idNumber(idNumber)
                    .fullName(fullName)
                    .dateOfBirth(dateOfBirth)
                    .gender(gender)
                    .address(address)
                    .portraitImageUrl(portraitImage)
                    .build();
        } catch (ClassCastException e) {
            log.error("Failed to parse FPT.AI response structure: {}", e.getMessage(), e);
            throw new EkycException("Invalid response format from OCR service");
        } catch (EkycException e) {
            throw e;
        } catch (Exception e) {
            log.error("OCR processing failed: {}", e.getMessage(), e);
            throw new EkycException("OCR processing failed: " + e.getMessage());
        }
    }

    private String getStringValue(Map<String, Object> map, String key) {
        Object value = map.get(key);
        return value != null ? value.toString() : "";
    }

    @Transactional
    @SuppressWarnings("unchecked")
    public LivenessResponse processLiveness(LivenessRequest request) {
        log.info("Processing liveness for session: {}", request.getSessionId());

        // Validate session
        EkycSession session = sessionRepository.findById(UUID.fromString(request.getSessionId()))
                .orElseThrow(() -> new EkycException("Session not found"));

        try {
            // Call FPT.AI Liveness
            Map<String, Object> result = fptAiService.callLivenessApi(request.getVideoBase64());
            log.debug("Liveness result: {}", result);

            // FPT.AI Liveness response structure: { "data": { "is_live": true, "score": 0.99 } }
            Object dataObj = result.get("data");
            if (dataObj == null) {
                throw new EkycException("FPT.AI returned null data for liveness check");
            }

            Map<String, Object> data = (Map<String, Object>) dataObj;

            // Safe casting for boolean and number
            Boolean isLive = getBooleanValue(data, "is_live");
            Double score = getDoubleValue(data, "score");

            log.info("Liveness check result: isLive={}, score={}", isLive, score);

            // Save biometric data
            BiometricData biometricData = BiometricData.builder()
                    .session(session)
                    .selfieVideoUrl(request.getVideoBase64()) // Storing base64 directly
                    .livenessScore(score)
                    .isLive(isLive)
                    .build();

            biometricDataRepository.save(biometricData);

            // Update session
            session.setStatus(EkycStatus.LIVENESS_COMPLETED);
            session.setCurrentStep(EkycStep.FACE_MATCH);
            sessionRepository.save(session);

            return LivenessResponse.builder()
                    .isLive(isLive)
                    .confidence(score)
                    .build();
        } catch (ClassCastException e) {
            log.error("Failed to parse FPT.AI liveness response: {}", e.getMessage(), e);
            throw new EkycException("Invalid response format from liveness service");
        } catch (EkycException e) {
            throw e;
        } catch (Exception e) {
            log.error("Liveness processing failed: {}", e.getMessage(), e);
            throw new EkycException("Liveness processing failed: " + e.getMessage());
        }
    }

    private Boolean getBooleanValue(Map<String, Object> map, String key) {
        Object value = map.get(key);
        if (value == null) return false;
        if (value instanceof Boolean) return (Boolean) value;
        return Boolean.parseBoolean(value.toString());
    }

    private Double getDoubleValue(Map<String, Object> map, String key) {
        Object value = map.get(key);
        if (value == null) return 0.0;
        if (value instanceof Number) return ((Number) value).doubleValue();
        try {
            return Double.parseDouble(value.toString());
        } catch (NumberFormatException e) {
            log.warn("Failed to parse double value for key {}: {}", key, value);
            return 0.0;
        }
    }

    @Transactional
    @SuppressWarnings("unchecked")
    public FaceMatchResponse processFaceMatch(String sessionId) {
        log.info("Processing face match for session: {}", sessionId);

        // Get session with relations
        EkycSession session = sessionRepository.findById(UUID.fromString(sessionId))
                .orElseThrow(() -> new EkycException("Session not found"));

        DocumentInfo docInfo = session.getDocumentInfo();
        BiometricData bioData = session.getBiometricData();

        if (docInfo == null || bioData == null) {
            throw new EkycException("Missing required data for face matching");
        }

        try {
            // Extract frame from video (simplified - using video base64 directly)
            String portraitImage = docInfo.getPortraitImageUrl();
            String selfieImage = bioData.getSelfieVideoUrl(); // In production, extract frame from video

            // Call FPT.AI Face Match
            Map<String, Object> result = fptAiService.callFaceMatchApi(portraitImage, selfieImage);
            log.debug("Face match result: {}", result);

            // FPT.AI Face Match response structure: { "data": { "similarity": 0.95 } }
            Object dataObj = result.get("data");
            if (dataObj == null) {
                throw new EkycException("FPT.AI returned null data for face match");
            }

            Map<String, Object> data = (Map<String, Object>) dataObj;

            Double similarity = getDoubleValue(data, "similarity");
            Boolean isMatched = similarity >= 0.85;

            log.info("Face match result: similarity={}, isMatched={}", similarity, isMatched);

            // Update biometric data
            bioData.setFaceMatchScore(similarity);
            bioData.setIsMatched(isMatched);
            biometricDataRepository.save(bioData);

            // Update session
            if (isMatched) {
                session.setStatus(EkycStatus.COMPLETED);
                session.setCurrentStep(EkycStep.COMPLETE);
            } else {
                session.setStatus(EkycStatus.FAILED);
            }
            sessionRepository.save(session);

            return FaceMatchResponse.builder()
                    .isMatched(isMatched)
                    .confidence(similarity)
                    .build();
        } catch (ClassCastException e) {
            log.error("Failed to parse FPT.AI face match response: {}", e.getMessage(), e);
            throw new EkycException("Invalid response format from face match service");
        } catch (EkycException e) {
            throw e;
        } catch (Exception e) {
            log.error("Face match processing failed: {}", e.getMessage(), e);
            throw new EkycException("Face match processing failed: " + e.getMessage());
        }
    }

    private LocalDate parseDateOfBirth(String dobStr) {
        try {
            DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
            return LocalDate.parse(dobStr, formatter);
        } catch (Exception e) {
            log.warn("Failed to parse date: {}", dobStr);
            return null;
        }
    }
}

package com.ebanking.ekycservice.service;

import com.ebanking.ekycservice.config.FptAiConfig;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.*;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

import java.util.Map;

@Service
@RequiredArgsConstructor
@Slf4j
public class FptAiService {
    private final FptAiConfig fptAiConfig;
    private final RestTemplate restTemplate =new RestTemplate();

    @SuppressWarnings("unchecked")
    public Map<String, Object> callOrcApi(String imageBase64) {
        try {
            //Mục đích: Gọi API OCR của FPT.AI để trích xuất thông tin từ hình ảnh

            // Clean base64 string - loại bỏ whitespace, newlines, và data URI prefix nếu có
            String cleanBase64 = cleanBase64String(imageBase64);

            log.info("Calling FPT.AI OCR API with image size: {} characters", cleanBase64.length());

            //chuẩn bị headers gồm api-key và content-type là application/json
            HttpHeaders headers = new HttpHeaders();
            headers.set("api-key", fptAiConfig.getApiKey());
            headers.setContentType(MediaType.APPLICATION_JSON);

            // Theo FPT.AI documentation, format body phải là:
            // {"image": "base64_string"}
            // KHÔNG gửi get_thumb nếu API không yêu cầu
            Map<String, Object> requestBody = Map.of("image", cleanBase64);

            // chuẩn bị entity để gửi request đến API OCR
            HttpEntity<Map<String, Object>> entity = new HttpEntity<>(requestBody, headers);

            log.debug("Sending request to FPT.AI OCR: {}", fptAiConfig.getOcrUrl());

            // gửi request đến API OCR và nhận response
            ResponseEntity<Map<String, Object>> response = restTemplate.exchange(
                    fptAiConfig.getOcrUrl(),
                    HttpMethod.POST,
                    entity,
                    (Class<Map<String, Object>>)(Class<?>)Map.class
            );

            log.info("FPT.AI OCR response status: {}", response.getStatusCode());

        // trả về body của response chứa kết quả OCR
        return response.getBody();
        } catch (Exception e) {
            log.error("FPT.AI OCR failed: {}", e.getMessage(), e);
            throw new RuntimeException("OCR processing failed: " + e.getMessage());
        }
    }

    /**
     * Clean base64 string để đảm bảo format đúng cho FPT.AI API
     * - Loại bỏ data URI prefix (data:image/...;base64,)
     * - Loại bỏ whitespace và newlines
     * - Trim spaces
     */
    private String cleanBase64String(String base64) {
        if (base64 == null || base64.isEmpty()) {
            throw new IllegalArgumentException("Base64 string cannot be null or empty");
        }

        // Loại bỏ data URI prefix nếu có
        String cleaned = base64;
        if (cleaned.contains("base64,")) {
            cleaned = cleaned.substring(cleaned.indexOf("base64,") + 7);
        }

        // Loại bỏ tất cả whitespace và newlines
        cleaned = cleaned.replaceAll("\\s+", "");

        return cleaned.trim();
    }

    @SuppressWarnings("unchecked")
    public Map<String, Object> callLivenessApi(String videoBase64) {
        try {
            // Mục đích: Gọi API Liveness của FPT.AI để kiểm tra tính sống động của khuôn mặt trong video
            // chuẩn bị headers gồm api-key và content-type là application/json
            HttpHeaders headers = new HttpHeaders();
            headers.set("api-key", fptAiConfig.getApiKey());
            headers.setContentType(MediaType.APPLICATION_JSON);

            // chuẩn bị body gồm có video dạng base64
            Map<String, Object> requestBody = Map.of("video", videoBase64);
            // chuẩn bị entity để gửi request đến API Liveness
            HttpEntity<Map<String, Object>> entity = new HttpEntity<>(requestBody, headers);
            // gửi request đến API Liveness và nhận response gồm body chứa kết quả kiểm tra liveness
            ResponseEntity<Map<String, Object>> response = restTemplate.exchange(
                    fptAiConfig.getLivenessUrl(),
                    HttpMethod.POST,
                    entity,
                    (Class<Map<String, Object>>)(Class<?>)Map.class
            );

            return response.getBody();

        } catch (Exception e) {
            log.error("FPT.AI Liveness failed", e);
            throw new RuntimeException("Liveness check failed: " + e.getMessage());
        }
    }

    @SuppressWarnings("unchecked")
    public Map<String, Object> callFaceMatchApi(String image1Base64, String image2Base64) {
        try {
            // Mục đích: Gọi API Face Match của FPT.AI để so sánh hai hình ảnh khuôn mặt
            // chuẩn bị headers gồm api-key và content-type là application/json
            HttpHeaders headers = new HttpHeaders();
            headers.set("api-key", fptAiConfig.getApiKey());
            headers.setContentType(MediaType.APPLICATION_JSON);
            // chuẩn bị body gồm có hai hình ảnh dạng base64 để so sánh
            Map<String, Object> requestBody = Map.of(
                    "image1", image1Base64,
                    "image2", image2Base64
            );
            // chuẩn bị entity để gửi request đến API Face Match
            HttpEntity<Map<String, Object>> entity = new HttpEntity<>(requestBody, headers);
            // gửi request đến API Face Match và nhận response gồm body chứa kết quả so sánh
            ResponseEntity<Map<String, Object>> response = restTemplate.exchange(
                    fptAiConfig.getFaceMatchUrl(),
                    HttpMethod.POST,
                    entity,
                    (Class<Map<String, Object>>)(Class<?>)Map.class
            );

            return response.getBody();

        } catch (Exception e) {
            log.error("FPT.AI Face Match failed", e);
            throw new RuntimeException("Face matching failed: " + e.getMessage());
        }
    }
}

package com.ebanking.ekycservice.service;

import com.ebanking.ekycservice.config.FptAiConfig;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.*;
import org.springframework.stereotype.Service;
import org.springframework.web.client.HttpClientErrorException;
import org.springframework.web.client.HttpServerErrorException;
import org.springframework.web.client.RestTemplate;

import java.util.Map;

@Service
@RequiredArgsConstructor
@Slf4j
public class FptAiService {
    private final FptAiConfig fptAiConfig;
    private final RestTemplate restTemplate = new RestTemplate();
    private final ObjectMapper objectMapper = new ObjectMapper();

    @SuppressWarnings("unchecked")
    public Map<String, Object> callOrcApi(String imageBase64) {
        try {
            //Mục đích: Gọi API OCR của FPT.AI để trích xuất thông tin từ hình ảnh

            // Clean base64 string - loại bỏ whitespace, newlines, và data URI prefix nếu có
            String cleanBase64 = cleanBase64String(imageBase64);

            log.info("Calling FPT.AI OCR API with image size: {} characters", cleanBase64.length());

            //chuẩn bị headers gồm api-key và content-type là application/json
            HttpHeaders headers = new HttpHeaders();
            headers.set("api-key", fptAiConfig.getApiKey());
            headers.setContentType(MediaType.APPLICATION_JSON);

            // Theo FPT.AI documentation, format body phải là:
            // {"image": "base64_string"}
            // KHÔNG gửi get_thumb nếu API không yêu cầu
            Map<String, Object> requestBody = Map.of("image", cleanBase64);

            // chuẩn bị entity để gửi request đến API OCR
            HttpEntity<Map<String, Object>> entity = new HttpEntity<>(requestBody, headers);

            log.debug("Sending request to FPT.AI OCR: {}", fptAiConfig.getOcrUrl());

            // gửi request đến API OCR và nhận response
            ResponseEntity<String> response = restTemplate.exchange(
                    fptAiConfig.getOcrUrl(),
                    HttpMethod.POST,
                    entity,
                    String.class
            );

            log.info("FPT.AI OCR response status: {}", response.getStatusCode());
            log.debug("FPT.AI OCR response body: {}", response.getBody());

            // Parse response body to Map
            Map<String, Object> responseBody = objectMapper.readValue(response.getBody(), Map.class);

            // Check error code in response
            Object errorCode = responseBody.get("errorCode");
            if (errorCode != null && !errorCode.toString().equals("0")) {
                String errorMessage = (String) responseBody.get("errorMessage");
                log.error("FPT.AI OCR API returned error: code={}, message={}", errorCode, errorMessage);
                throw new RuntimeException("FPT.AI OCR error: " + errorMessage);
            }

            // trả về body của response chứa kết quả OCR
            return responseBody;
        } catch (HttpClientErrorException | HttpServerErrorException e) {
            log.error("FPT.AI OCR HTTP error: status={}, body={}", e.getStatusCode(), e.getResponseBodyAsString());
            throw new RuntimeException("OCR API request failed: " + e.getMessage());
        } catch (Exception e) {
            log.error("FPT.AI OCR failed: {}", e.getMessage(), e);
            throw new RuntimeException("OCR processing failed: " + e.getMessage());
        }
    }

    /**
     * Clean base64 string để đảm bảo format đúng cho FPT.AI API
     * - Loại bỏ data URI prefix (data:image/...;base64,)
     * - Loại bỏ whitespace và newlines
     * - Trim spaces
     */
    private String cleanBase64String(String base64) {
        if (base64 == null || base64.isEmpty()) {
            throw new IllegalArgumentException("Base64 string cannot be null or empty");
        }

        // Loại bỏ data URI prefix nếu có
        String cleaned = base64;
        if (cleaned.contains("base64,")) {
            cleaned = cleaned.substring(cleaned.indexOf("base64,") + 7);
        }

        // Loại bỏ tất cả whitespace và newlines
        cleaned = cleaned.replaceAll("\\s+", "");

        return cleaned.trim();
    }

    @SuppressWarnings("unchecked")
    public Map<String, Object> callLivenessApi(String videoBase64) {
        try {
            log.info("Calling FPT.AI Liveness API with video size: {} characters", videoBase64.length());

            // Mục đích: Gọi API Liveness của FPT.AI để kiểm tra tính sống động của khuôn mặt trong video
            // chuẩn bị headers gồm api-key và content-type là application/json
            HttpHeaders headers = new HttpHeaders();
            headers.set("api-key", fptAiConfig.getApiKey());
            headers.setContentType(MediaType.APPLICATION_JSON);

            // chuẩn bị body gồm có video dạng base64
            Map<String, Object> requestBody = Map.of("video", videoBase64);
            // chuẩn bị entity để gửi request đến API Liveness
            HttpEntity<Map<String, Object>> entity = new HttpEntity<>(requestBody, headers);

            log.debug("Sending request to FPT.AI Liveness: {}", fptAiConfig.getLivenessUrl());

            // gửi request đến API Liveness và nhận response gồm body chứa kết quả kiểm tra liveness
            ResponseEntity<String> response = restTemplate.exchange(
                    fptAiConfig.getLivenessUrl(),
                    HttpMethod.POST,
                    entity,
                    String.class
            );

            log.info("FPT.AI Liveness response status: {}", response.getStatusCode());
            log.debug("FPT.AI Liveness response body: {}", response.getBody());

            // Parse response body to Map
            Map<String, Object> responseBody = objectMapper.readValue(response.getBody(), Map.class);

            // Check error code in response
            Object errorCode = responseBody.get("errorCode");
            if (errorCode != null && !errorCode.toString().equals("0")) {
                String errorMessage = (String) responseBody.get("errorMessage");
                log.error("FPT.AI Liveness API returned error: code={}, message={}", errorCode, errorMessage);
                throw new RuntimeException("FPT.AI Liveness error: " + errorMessage);
            }

            return responseBody;

        } catch (HttpClientErrorException | HttpServerErrorException e) {
            log.error("FPT.AI Liveness HTTP error: status={}, body={}", e.getStatusCode(), e.getResponseBodyAsString());
            throw new RuntimeException("Liveness API request failed: " + e.getMessage());
        } catch (Exception e) {
            log.error("FPT.AI Liveness failed: {}", e.getMessage(), e);
            throw new RuntimeException("Liveness check failed: " + e.getMessage());
        }
    }

    @SuppressWarnings("unchecked")
    public Map<String, Object> callFaceMatchApi(String image1Base64, String image2Base64) {
        try {
            log.info("Calling FPT.AI Face Match API");

            // Mục đích: Gọi API Face Match của FPT.AI để so sánh hai hình ảnh khuôn mặt
            // chuẩn bị headers gồm api-key và content-type là application/json
            HttpHeaders headers = new HttpHeaders();
            headers.set("api-key", fptAiConfig.getApiKey());
            headers.setContentType(MediaType.APPLICATION_JSON);
            // chuẩn bị body gồm có hai hình ảnh dạng base64 để so sánh
            Map<String, Object> requestBody = Map.of(
                    "image1", image1Base64,
                    "image2", image2Base64
            );
            // chuẩn bị entity để gửi request đến API Face Match
            HttpEntity<Map<String, Object>> entity = new HttpEntity<>(requestBody, headers);

            log.debug("Sending request to FPT.AI Face Match: {}", fptAiConfig.getFaceMatchUrl());

            // gửi request đến API Face Match và nhận response gồm body chứa kết quả so sánh
            ResponseEntity<String> response = restTemplate.exchange(
                    fptAiConfig.getFaceMatchUrl(),
                    HttpMethod.POST,
                    entity,
                    String.class
            );

            log.info("FPT.AI Face Match response status: {}", response.getStatusCode());
            log.debug("FPT.AI Face Match response body: {}", response.getBody());

            // Parse response body to Map
            Map<String, Object> responseBody = objectMapper.readValue(response.getBody(), Map.class);

            // Check error code in response
            Object errorCode = responseBody.get("errorCode");
            if (errorCode != null && !errorCode.toString().equals("0")) {
                String errorMessage = (String) responseBody.get("errorMessage");
                log.error("FPT.AI Face Match API returned error: code={}, message={}", errorCode, errorMessage);
                throw new RuntimeException("FPT.AI Face Match error: " + errorMessage);
            }

            return responseBody;

        } catch (HttpClientErrorException | HttpServerErrorException e) {
            log.error("FPT.AI Face Match HTTP error: status={}, body={}", e.getStatusCode(), e.getResponseBodyAsString());
            throw new RuntimeException("Face Match API request failed: " + e.getMessage());
        } catch (Exception e) {
            log.error("FPT.AI Face Match failed: {}", e.getMessage(), e);
            throw new RuntimeException("Face matching failed: " + e.getMessage());
        }
    }
}
